package com.rezoxnemesis.videostudio;
import ai.onnxruntime.*;
import ai.onnxruntime.platform.Fp16Conversions;
import org.json.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.annotation.Config;
import java.io.*;
import java.nio.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.*;
import static org.junit.Assert.*;

/** Opt-in REAL VideoStudio ORT CPU graph routing, with numeric diagnostics, never artwork. */
@RunWith(RobolectricTestRunner.class) @Config(sdk=33,manifest=Config.NONE)
public class LocalDrawingPlusGraphRuntimeProbeTest {
 private static final int[] INNER={320,320,640,640,1280,1280,1280,1280,1280,640,640,640,320,320,320,1280};
 private static final long[][] RESIDUALS={{1,320,64,64},{1,320,64,64},{1,320,64,64},{1,320,32,32},{1,640,32,32},{1,640,32,32},{1,640,16,16},{1,1280,16,16},{1,1280,16,16},{1,1280,8,8},{1,1280,8,8},{1,1280,8,8},{1,1280,8,8}};
 private OrtEnvironment environment;
 @Test public void actualPenultimatePlusFaceAnd48PortUnetPreserveNumericAppearanceStructureAndZeroVNeutrality()throws Exception {
  String path=System.getenv("VIDEOSTUDIO_PLUS_GRAPH_PROBE");Assume.assumeTrue("Explicit real CPU graph probe only",path!=null&&!path.isEmpty());JSONObject config=new JSONObject(new String(Files.readAllBytes(new File(path).toPath()),StandardCharsets.UTF_8));File directory=new File(config.getString("outputDirectory"));assertTrue(directory.mkdirs()||directory.isDirectory());File evidence=new File(directory,"native-plus-graph-runtime.json");assertFalse("Preserve old probe evidence",evidence.exists());
  JSONObject report=new JSONObject().put("status","RUNNING").put("sourceCommit",config.getString("sourceCommit")).put("sourceState",config.getString("sourceState")).put("appVersion",AppProtocol.APP_VERSION).put("intendedVersion","4.10.8 WIP, not installed/signed").put("inferenceExecuted",false).put("inferenceAttempted",true).put("inferenceKind","Numeric graph routing only; no denoising schedule, VAE decode or artwork").put("renderer","VideoStudio LocalDrawingEngine cancellation-aware ONNX Runtime CPU/JNI runner under Robolectric").put("phoneExecution",false).put("creativeScenarios",0).put("likenessAccepted",false).put("oldFourTokenEquivalenceVerified",false).put("zeroVTolerance",0).put("oldFourTokenPlannedMaxAbsBudget",0.02).put("oldFourTokenPlannedRmsBudget",0.003).put("startedAt",System.currentTimeMillis());write(evidence,report);
  try(LocalDrawingEngine runner=new LocalDrawingEngine()){
   environment=OrtEnvironment.getEnvironment();
   File clip=pinned(config,"clip","8f6c9781e0a6de096ac0e6160e067f8b94001dabef279f7fa70dff150e4e454a"),unet=pinned(config,"unet","d53c027c7a0ea50f737fe57a2f68ab5f980b0c6199c4980cb96ff66de5da00f6"),head=pinned(config,"head","d30b57dfb4f90198486901143eae5ba8d8f2179b8677e475fcb225e696826c33"),control=pinned(config,"controlnet","399358929322eb5bb2f0e141e23486397a29ec871e4efa625c0f2ba4d418c698");
   float[] normalZeroPixels=new float[3*224*224],referencePixels=new float[normalZeroPixels.length];for(int i=0;i<referencePixels.length;i++)referencePixels[i]=(float)(.4*Math.sin(i*.017)+.15*Math.cos(i*.003));float[] referenceHidden,unconditionalHidden;
   try(OrtSession session=runner.open(clip.getParentFile(),clip.getName())){report.put("clipInputs",metadata(session.getInputInfo())).put("clipOutputs",metadata(session.getOutputInfo()));shape(session.getInputInfo().get("pixel_values"),OnnxJavaType.FLOAT16,1,3,224,224);shape(session.getOutputInfo().get("penultimate_hidden_states"),OnnxJavaType.FLOAT16,1,257,1280);referenceHidden=encode(runner,session,referencePixels);unconditionalHidden=encode(runner,session,normalZeroPixels);}
   report.put("inferenceExecuted",true);JSONObject hiddenDelta=difference(referenceHidden,unconditionalHidden);assertTrue(hiddenDelta.toString(),hiddenDelta.getDouble("meanAbs")>1e-5);assertTrue("Actual CLIP(zero NORMALIZED pixels) is not a zero hidden array",rms(unconditionalHidden)>1e-5);report.put("unconditionalInput","All zero normalized FP16 pixel tensor, NOT zero hidden embedding").put("unconditionalHiddenRms",rms(unconditionalHidden)).put("penultimateRouteDelta",hiddenDelta);write(evidence,report);
   float[][] referenceKv,unconditionalKv;try(OrtSession session=runner.open(head.getParentFile(),head.getName())){report.put("headInputs",metadata(session.getInputInfo())).put("headOutputs",metadata(session.getOutputInfo()));assertEquals(1,session.getInputInfo().size());assertEquals(32,session.getOutputInfo().size());shape(session.getInputInfo().get("hidden"),OnnxJavaType.FLOAT,1,257,1280);referenceKv=head(runner,session,referenceHidden);unconditionalKv=head(runner,session,unconditionalHidden);}referenceHidden=null;unconditionalHidden=null;
   float[] latents=new float[4*64*64],text=new float[77*768];for(int i=0;i<latents.length;i++)latents[i]=(float)(.15*Math.sin(i*.013));for(int i=0;i<text.length;i++)text[i]=(float)(.05*Math.cos(i*.007));float[][] residuals;
   try(OrtSession session=runner.open(control.getParentFile(),control.getName())){report.put("controlInputs",metadata(session.getInputInfo())).put("controlOutputs",metadata(session.getOutputInfo()));residuals=control(runner,session,latents,text);}write(evidence,report);
   float[][] zeroResiduals=new float[13][];for(int i=0;i<13;i++)zeroResiduals[i]=new float[count(RESIDUALS[i])];
   try(OrtSession session=runner.open(unet.getParentFile(),unet.getName())){
    Map<String,NodeInfo> inputs=session.getInputInfo();assertEquals(48,inputs.size());assertFalse(inputs.containsKey("image_embeds"));shape(inputs.get("sample"),OnnxJavaType.FLOAT16,1,4,64,64);shape(inputs.get("timestep"),OnnxJavaType.FLOAT16,1);shape(inputs.get("encoder_hidden_states"),OnnxJavaType.FLOAT16,1,77,768);for(int i=0;i<13;i++)shape(inputs.get(residual(i)),OnnxJavaType.FLOAT16,RESIDUALS[i]);for(int i=0;i<16;i++){shape(inputs.get("ipk_"+i),OnnxJavaType.FLOAT16,1,INNER[i],16);shape(inputs.get("ipv_"+i),OnnxJavaType.FLOAT16,1,16,INNER[i]);}report.put("unetInputs",metadata(inputs)).put("unetOutputs",metadata(session.getOutputInfo()));write(evidence,report);
    float[] reference=predict(runner,session,latents,text,referenceKv,zeroResiduals,false),unconditional=predict(runner,session,latents,text,unconditionalKv,zeroResiduals,false),structured=predict(runner,session,latents,text,referenceKv,residuals,false);JSONObject appearanceDelta=difference(reference,unconditional),structureDelta=difference(reference,structured);report.put("appearanceRouteDelta",appearanceDelta).put("structureRouteDelta",structureDelta);assertTrue(appearanceDelta.toString(),appearanceDelta.getDouble("meanAbs")>1e-5);assertTrue(structureDelta.toString(),structureDelta.getDouble("meanAbs")>1e-5);
    float[] zeroVWithReferenceK=predict(runner,session,latents,text,referenceKv,residuals,true),zeroVWithUnconditionalK=predict(runner,session,latents,text,unconditionalKv,residuals,true);JSONObject neutral=difference(zeroVWithReferenceK,zeroVWithUnconditionalK);report.put("zeroVDifferentKDelta",neutral).put("unetForwardPasses",5).put("controlForwardPasses",1).put("clipForwardPasses",2).put("headForwardPasses",2);assertEquals("Zero V must remove appearance even when K changes",0,neutral.getDouble("maxAbs"),0);
   }
   report.put("runtimeVersion",runner.runtimeVersion()).put("status","TECHNICAL_GRAPH_ROUTES_PASS_NO_ARTWORK_OR_BASELINE_EQUIVALENCE");
  }catch(Exception|AssertionError|LinkageError failure){report.put("status","FAIL").put("error",failure.toString());throw failure;}
  finally{report.put("finishedAt",System.currentTimeMillis()).put("hostProcessMemory",memory());write(evidence,report);}
 }
 private File pinned(JSONObject config,String key,String sha)throws Exception {File file=new File(config.getString(key));assertEquals("Pinned public/derived graph "+key,sha,LocalDrawingModels.hash(file));return file;}
 private float[] encode(LocalDrawingEngine runner,OrtSession session,float[] input)throws Exception {try(OnnxTensor tensor=half(input,1,3,224,224);OrtSession.Result result=runner.run(session,Collections.singletonMap("pixel_values",tensor))){return values(result,"penultimate_hidden_states",OnnxJavaType.FLOAT16,1,257,1280);}}
 private float[][] head(LocalDrawingEngine runner,OrtSession session,float[] hidden)throws Exception {try(OnnxTensor tensor=runner.tensor(hidden,1,257,1280);OrtSession.Result result=runner.run(session,Collections.singletonMap("hidden",tensor))){float[][] outputs=new float[32][];for(int i=0;i<16;i++){outputs[i]=values(result,"ipk_"+i,OnnxJavaType.FLOAT,1,INNER[i],16);outputs[16+i]=values(result,"ipv_"+i,OnnxJavaType.FLOAT,1,16,INNER[i]);}return outputs;}}
 private float[][] control(LocalDrawingEngine runner,OrtSession session,float[] latents,float[] text)throws Exception {float[] hint=new float[3*512*512];for(int y=0;y<512;y++)for(int x=0;x<512;x++)if(x%64<2||y%64<2)for(int c=0;c<3;c++)hint[c*512*512+y*512+x]=1;try(OnnxTensor sample=half(latents,1,4,64,64);OnnxTensor timestep=half(new float[]{500},1);OnnxTensor embedding=half(text,1,77,768);OnnxTensor guide=half(hint,1,3,512,512)){Map<String,OnnxTensor> inputs=new LinkedHashMap<>();inputs.put("sample",sample);inputs.put("timestep",timestep);inputs.put("encoder_hidden_states",embedding);inputs.put("canny_image",guide);try(OrtSession.Result result=runner.run(session,inputs)){float[][] outputs=new float[13][];for(int i=0;i<13;i++)outputs[i]=values(result,residual(i),OnnxJavaType.FLOAT16,RESIDUALS[i]);return outputs;}}}
 private float[] predict(LocalDrawingEngine runner,OrtSession session,float[] latents,float[] text,float[][] kv,float[][] residuals,boolean zeroV)throws Exception {Map<String,OnnxTensor> inputs=new LinkedHashMap<>();List<OnnxTensor> owned=new ArrayList<>();try{put(inputs,owned,"sample",half(latents,1,4,64,64));put(inputs,owned,"timestep",half(new float[]{500},1));put(inputs,owned,"encoder_hidden_states",half(text,1,77,768));for(int i=0;i<13;i++)put(inputs,owned,residual(i),half(residuals[i],RESIDUALS[i]));for(int i=0;i<16;i++){put(inputs,owned,"ipk_"+i,half(kv[i],1,INNER[i],16));put(inputs,owned,"ipv_"+i,half(zeroV?new float[kv[16+i].length]:kv[16+i],1,16,INNER[i]));}try(OrtSession.Result result=runner.run(session,inputs)){return values(result,"noise_pred",OnnxJavaType.FLOAT16,1,4,64,64);}}finally{for(OnnxTensor tensor:owned)tensor.close();}}
 private static void put(Map<String,OnnxTensor> map,List<OnnxTensor> owned,String name,OnnxTensor value){owned.add(value);map.put(name,value);}
 private OnnxTensor half(float[] values,long...shape)throws Exception {return OnnxTensor.createTensor(environment,Fp16Conversions.convertFloatBufferToFp16Buffer(FloatBuffer.wrap(values)),shape,OnnxJavaType.FLOAT16);}
 private static float[] values(OrtSession.Result result,String name,OnnxJavaType type,long...shape)throws Exception {OnnxValue value=result.get(name).orElseThrow(()->new IllegalStateException("Missing output "+name));assertTrue(value instanceof OnnxTensor);OnnxTensor tensor=(OnnxTensor)value;assertEquals(type,tensor.getInfo().type);assertArrayEquals(shape,tensor.getInfo().getShape());FloatBuffer buffer=tensor.getFloatBuffer();float[] output=new float[buffer.remaining()];buffer.get(output);assertEquals(count(shape),output.length);for(float number:output)assertTrue("Finite actual model output "+name,Float.isFinite(number));return output;}
 private static JSONObject metadata(Map<String,NodeInfo> values)throws Exception {JSONObject out=new JSONObject();for(Map.Entry<String,NodeInfo> item:values.entrySet()){assertTrue(item.getValue().getInfo() instanceof TensorInfo);TensorInfo tensor=(TensorInfo)item.getValue().getInfo();out.put(item.getKey(),new JSONObject().put("type",tensor.type.toString()).put("shape",new JSONArray(tensor.getShape())));}return out;}
 private static void shape(NodeInfo value,OnnxJavaType type,long...shape){assertNotNull(value);assertTrue(value.getInfo() instanceof TensorInfo);TensorInfo tensor=(TensorInfo)value.getInfo();assertEquals(type,tensor.type);long[] actual=tensor.getShape();assertEquals(shape.length,actual.length);for(int i=0;i<shape.length;i++)assertTrue("Exact dimension except dynamic batch",actual[i]==shape[i]||i==0&&actual[i]==-1);}
 private static JSONObject difference(float[] a,float[] b)throws Exception {assertEquals(a.length,b.length);double abs=0,squares=0,max=0;for(int i=0;i<a.length;i++){double d=Math.abs((double)a[i]-b[i]);abs+=d;squares+=d*d;max=Math.max(max,d);}return new JSONObject().put("maxAbs",max).put("meanAbs",abs/a.length).put("rms",Math.sqrt(squares/a.length));}
 private static double rms(float[] values){double sum=0;for(float value:values)sum+=(double)value*value;return Math.sqrt(sum/values.length);}
 private static int count(long...shape){int count=1;for(long dimension:shape)count=Math.multiplyExact(count,(int)dimension);return count;}
 private static String residual(int i){return i<12?"down_residual_"+i:"mid_residual";}
 private static JSONObject memory(){JSONObject out=new JSONObject();try{for(String line:Files.readAllLines(new File("/proc/self/status").toPath(),StandardCharsets.UTF_8))if(line.startsWith("VmRSS:")||line.startsWith("VmHWM:"))out.put(line.substring(0,line.indexOf(':')),line.substring(line.indexOf(':')+1).trim());out.put("scope","Host test process; not phone or codec/GPU evidence");}catch(Exception ignored){}return out;}
 private static void write(File file,JSONObject object)throws Exception {Files.write(file.toPath(),object.toString(2).getBytes(StandardCharsets.UTF_8));}
}
